BeginPlay()
{
    CreateAgent(Day)
        .Team(Morninghollow.Day)
        .Bot(DefaultBot)
        .Resources(StartingResources);

    CreateAgent(Night)
        .Team(Morninghollow.Night)
        .Bot(DefaultBot)
        .Resources(StartingResources);

    Spawn(Stargate)
        .Location(-50, 0, 0)
        .Owner(Day);

    Spawn(Stargate)
        .Location(50, 0, 0)
        .Owner(Night);

    Spawn(StandardApex)
        .Location(0, 0, 0)
        .Team(Morninghollow.Day)
        .Controller(Player1);
}
